99:SetupOutcome ProviderKeySetup::finish_ok()
100:{
101:    SetupOutcome outcome;
102:    outcome.ok         = true;
103:    outcome.elapsed_ms = elapsed_ms();
104:    // Drop the probe turn so the verified service is handed over idle, with
105:    // no partial response left for the user's first real message to inherit.
106:    m_candidate->cancel();
107:    outcome.service = std::move(m_candidate);
108:    m_candidate.reset();
109:    return outcome;
110:}
