  1	// Composer input rules from the handoff: Enter sends, Shift+Enter inserts a
  2	// newline, and Enter during IME composition accepts the composition without
  3	// sending. Normal selection, clipboard, and focus behavior are left to the
  4	// browser engine. The in-progress draft is reported (debounced) so the host
  5	// can keep it in the local recovery store; reconnecting restores it via
  6	// initialText.
  7	//
  8	// Attachments enter through a file picker, drag-and-drop, or pasting an image;
  9	// staged attachments render as removable chips, and a message may be sent with
 10	// attachments and no text. The host owns decoding and storage — the composer
 11	// only hands it files.
 12	
 13	import { ChangeEvent, ClipboardEvent, DragEvent, KeyboardEvent, ReactNode, useEffect, useRef, useState } from 'react';
 14	import { AttachmentInfo, AttachmentSource } from '../bridge/protocol';
 15	import { AttachmentChip } from './AttachmentChip';
 16	
 17	interface Props {
 18	  disabled: boolean;
 19	  disabledReason?: string;
 20	  streaming: boolean;
 21	  initialText?: string;
 22	  attachments: AttachmentInfo[]; // staged attachments only
 23	  onSend: (text: string) => void;
 24	  onStop: () => void;
 25	  onAttachFiles: (files: File[], source: AttachmentSource) => void;
 26	  onRemoveAttachment: (id: string) => void;
 27	  onDraftChange?: (text: string) => void;
 28	  draftDebounceMs?: number;
 29	  // Fired on the keystroke itself, not on the debounced draft save. Anything
 30	  // covering the thread uses this to get out of the way immediately.
 31	  onTyping?: () => void;
 32	  // A likely answer to what was just asked, rather than the standing
 33	  // invitation. The printer panel writes one per turn.
 34	  placeholder?: string;
 35	  // Labelled "Photo" instead of a bare paperclip: in the printer panel a
 36	  // picture is a primary way to say which printer this is, not an extra.
 37	  photoButton?: boolean;
 38	  // What the band says above the field when the field cannot be used as it
 39	  // is: the notice on an earlier chat, or a recovery alert.
 40	  notice?: ReactNode;
 41	  // False where nothing can be attached at all, so the action is left out
 42	  // rather than shown disabled: a read-only shell has only its field and Send.
 43	  attachable?: boolean;
 44	}
 45	
 46	export function Composer({
 47	  disabled,
 48	  disabledReason,
 49	  streaming,
 50	  initialText,
 51	  attachments,
 52	  onSend,
 53	  onStop,
 54	  onAttachFiles,
 55	  onRemoveAttachment,
 56	  onDraftChange,
 57	  draftDebounceMs = 300,
 58	  onTyping,
 59	  placeholder,
 60	  photoButton,
 61	  notice,
 62	  attachable = true,
 63	}: Props) {
 64	  const [text, setText] = useState(initialText ?? '');
 65	  const [dragging, setDragging] = useState(false);
 66	  const draftTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
 67	  const pendingDraft = useRef(false);
 68	  const latestText = useRef(initialText ?? '');
 69	  const fileInput = useRef<HTMLInputElement>(null);
 70	
 71	  // A recovered draft arrives after the first connect; apply it only while
 72	  // the composer is untouched so it never clobbers active typing.
 73	  const touched = useRef(false);
 74	  useEffect(() => {
 75	    if (!touched.current && initialText) { setText(initialText); latestText.current = initialText; }
 76	    // eslint-disable-next-line react-hooks/exhaustive-deps
 77	  }, [initialText]);
 78	
 79	  useEffect(() => {
 80	    return () => {
 81	      if (draftTimer.current !== null) clearTimeout(draftTimer.current);
 82	      if (pendingDraft.current) onDraftChange?.(latestText.current);
 83	    };
 84	  }, []);
 85	
 86	  const reportDraft = (value: string) => {
 87	    if (!onDraftChange) return;
 88	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
 89	    pendingDraft.current = true;
 90	    latestText.current = value;
 91	    draftTimer.current = setTimeout(() => { pendingDraft.current = false; onDraftChange(value); }, draftDebounceMs);
 92	  };
 93	
 94	  const hasSendable = attachments.some((a) => a.state === 'staged');
 95	  const canSend = (!!text.trim() || hasSendable) && !disabled && !streaming;
 96	
 97	  const send = () => {
 98	    if (!canSend) return;
 99	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
100	    pendingDraft.current = false;
101	    onSend(text.trim());
102	    setText('');
103	  };
104	
105	  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
106	    if (event.key !== 'Enter' || event.shiftKey) return;
107	    // 229 is the legacy IME-processing keyCode some engines still report.
108	    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
109	    event.preventDefault();
110	    send();
111	  };
112	
113	  const handleFiles = (files: FileList | null, source: AttachmentSource) => {
114	    if (!files || files.length === 0) return;
115	    onAttachFiles(Array.from(files), source);
116	  };
117	
118	  const handlePickerChange = (event: ChangeEvent<HTMLInputElement>) => {
119	    handleFiles(event.target.files, 'picker');
120	    event.target.value = ''; // allow re-picking the same file
121	  };
122	
123	  const handlePaste = (event: ClipboardEvent<HTMLTextAreaElement>) => {
124	    const files = Array.from(event.clipboardData.files ?? []);
125	    if (files.length > 0) {
126	      event.preventDefault();
127	      onAttachFiles(files, 'clipboard');
128	    }
129	  };
130	
131	  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
132	    event.preventDefault();
133	    setDragging(false);
134	    if (disabled) return;
135	    handleFiles(event.dataTransfer.files, 'drop');
136	  };
137	
138	  return (
139	    <div
140	      className={`composer${dragging ? ' dragging' : ''}`}
141	      onDragOver={(event) => {
142	        event.preventDefault();
143	        if (!disabled) setDragging(true);
144	      }}
145	      onDragLeave={() => setDragging(false)}
146	      onDrop={handleDrop}
147	    >
148	      {notice}
149	      <div className="composer-row">
150	        {attachable && <button
151	          type="button"
152	          className={photoButton ? 'attach-button attach-button-photo' : 'attach-button'}
153	          aria-label={photoButton ? 'Add a photo' : 'Attach a file'}
154	          disabled={disabled}
155	          onClick={() => fileInput.current?.click()}
156	        >
157	          {photoButton ? 'Photo' : 'Attach a file'}
158	        </button>}
159	        <input
160	          ref={fileInput}
161	          type="file"
162	          multiple
163	          className="attach-input"
164	          aria-hidden="true"
165	          tabIndex={-1}
166	          style={{ display: 'none' }}
167	          onChange={handlePickerChange}
168	        />
169	        <textarea
170	          aria-label="Message the Agent"
171	          placeholder={
172	            disabled
173	              ? disabledReason ?? 'The Agent is not available'
174	              : streaming
175	                ? 'Agent is responding…'
176	                // A staged photo waits for the person; it never sends itself.
177	                : photoButton && hasSendable
178	                  ? 'add a note, or just send'
179	                  : placeholder ?? 'Ask about this print…'
180	          }
181	          value={text}
182	          disabled={disabled}
183	          onChange={(event) => {
184	            touched.current = true;
185	            onTyping?.();
186	            setText(event.target.value);
187	            latestText.current = event.target.value;
188	            reportDraft(event.target.value);
189	          }}
190	          onKeyDown={handleKeyDown}
191	          onPaste={handlePaste}
192	          rows={1}
193	        />
194	        {streaming ? (
195	          <button type="button" className="composer-send composer-stop" onClick={onStop} aria-label="Stop generating">
196	            Stop
197	          </button>
198	        ) : (
199	          <button
200	            type="button"
201	            className="composer-send"
202	            onClick={send}
203	            disabled={!canSend}
204	            aria-label="Send message"
205	          >
206	            Send
207	          </button>
208	        )}
209	      </div>
210	      {attachments.length > 0 && (
211	        <div className="composer-attachments" aria-label="Staged attachments">
212	          {attachments.map((attachment) => (
213	            <AttachmentChip key={attachment.id} attachment={attachment} onRemove={onRemoveAttachment} />
214	          ))}
215	        </div>
216	      )}
217	    </div>
218	  );
219	}
  1	// Shared attachment row for the project and focused printer/filament chats.
  2	// Staged and failed items are removable; sent items are read-only. A decoded
  3	// photo has a thumbnail, while other files show their kind as a small badge.
  4	
  5	import { AttachmentInfo } from '../bridge/protocol';
  6	
  7	interface Props {
  8	  attachment: AttachmentInfo;
  9	  onRemove?: (id: string) => void;
 10	}
 11	
 12	const kindLabel: Record<string, string> = {
 13	  text: 'Text',
 14	  image: 'Image',
 15	  svg: 'SVG',
 16	  pdf: 'PDF',
 17	  gcode: 'G-code',
 18	  model: '3D model',
 19	  unsupported: 'Unsupported',
 20	};
 21	
 22	function sizeLabel(bytes: number): string {
 23	  if (bytes < 1024) return `${bytes} B`;
 24	  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
 25	  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
 26	}
 27	
 28	export function AttachmentChip({ attachment, onRemove }: Props) {
 29	  const errored = attachment.state === 'error';
 30	  const label = kindLabel[attachment.kind] ?? 'File';
