  1	// Guards the stylesheet's contract with resources/jusprin/ui/design-tokens.json:
  2	// colors, radii, and type metrics resolve through the custom properties that
  3	// tokens.ts emits, and spacing sits on the spacing scale. The file is read
  4	// from disk on purpose: importing the CSS under Vitest yields an empty string,
  5	// so a test written that way passes while asserting nothing.
  6	
  7	import { readFileSync } from 'node:fs';
  8	import { join } from 'node:path';
  9	import { describe, expect, it } from 'vitest';
 10	import { semanticVariableNames } from '@shared/tokens';
 11	import { staticVariableNames } from './tokens';
 12	
 13	const SPACING_SCALE = [0, 4, 8, 12, 16, 20, 24, 32, 40, 48];
 14	
 15	const source = readFileSync(join(__dirname, 'styles.css'), 'utf8');
 16	
 17	// Blank out comments but keep every newline so reported line numbers match
 18	// the file.
 19	const css = source.replace(/\/\*[\s\S]*?\*\//g, (comment) => comment.replace(/[^\n]/g, ' '));
 20	const lines = css.split('\n');
 21	
 22	// Line numbers (1-based) covered by an @font-face block, where font metrics
 23	// are the declaration of the face itself rather than a use of it.
 24	function fontFaceLines(): Set<number> {
 25	  const covered = new Set<number>();
 26	  let depth = 0;
 27	  let inFontFace = false;
 28	  lines.forEach((line, index) => {
 29	    if (!inFontFace && /@font-face\b/.test(line)) inFontFace = true;
 30	    if (inFontFace) covered.add(index + 1);
 31	    for (const ch of line) {
 32	      if (ch === '{') depth += 1;
 33	      if (ch === '}') {
 34	        depth -= 1;
 35	        if (inFontFace && depth === 0) inFontFace = false;
 36	      }
 37	    }
 38	  });
 39	  return covered;
 40	}
 41	
 42	const exemptLines = fontFaceLines();
 43	
 44	function offending(pattern: RegExp, extra?: (line: string) => boolean): string[] {
 45	  const hits: string[] = [];
 46	  lines.forEach((line, index) => {
 47	    const number = index + 1;
 48	    if (exemptLines.has(number)) return;
 49	    if (pattern.test(line) && (!extra || extra(line))) hits.push(`${number}: ${line.trim()}`);
 50	  });
 51	  return hits;
 52	}
 53	
 54	describe('styles.css stays on the design tokens', () => {
 55	  it('was actually read', () => {
 56	    expect(source.trim().length).toBeGreaterThan(0);
 57	  });
 58	
 59	  it('carries no literal color', () => {
 60	    expect(offending(/#[0-9a-fA-F]{3,8}\b|\b(rgba?|hsla?)\(/)).toEqual([]);
 61	  });
 62	
 63	  it('carries no pixel border-radius', () => {
 64	    expect(offending(/border-radius\s*:[^;]*\d+px/)).toEqual([]);
 65	  });
 66	
 67	  // The patterns match after a `{` or `;` as well as at the start of a line,
 68	  // so a single-line rule cannot slip past them.
 69	  it('sets type only through the role variables', () => {
 70	    expect(offending(/(?:^|[{;])\s*(font-size|line-height|font-weight)\s*:/)).toEqual([]);
 71	    // A `font` shorthand with a literal size or line height would bypass the
 72	    // check above.
 73	    expect(offending(/(?:^|[{;])\s*font\s*:[^;]*\d+px/)).toEqual([]);
 74	  });
 75	
 76	  it('asks only for variables that tokens.ts emits', () => {
 77	    const emitted = new Set([...staticVariableNames(), ...semanticVariableNames()]);
 78	    expect(emitted).toContain('--font-body-bold');
 79	    expect(emitted).toContain('--button-secondary-padding');
 80	    expect(emitted).toContain('--progress-height');
 81	    expect(emitted).toContain('--action-primary-text');
 82	    const requested = [
 83	      ...css.matchAll(/var\((--(?:radius|font|button|progress|action|text|surface|border|status)-[\w-]+)\)/g),
 84	    ].map((m) => m[1]);
 85	    expect(requested.length).toBeGreaterThan(0);
 86	    expect(requested.filter((name) => !emitted.has(name))).toEqual([]);
 87	  });
 88	
 89	  it('keeps padding, margin, and gap on the spacing scale', () => {
 90	    const offScale = offending(/^\s*(padding|margin|gap|row-gap|column-gap)(-[a-z]+)?\s*:/, (line) => {
 91	      const value = line.replace(/^[^:]*:/, '');
 92	      const pixels = [...value.matchAll(/(-?\d+(?:\.\d+)?)px/g)].map((m) => Math.abs(Number(m[1])));
 93	      return pixels.some((px) => !SPACING_SCALE.includes(px));
 94	    });
 95	    expect(offScale).toEqual([]);
 96	  });
 97	
 98	  // The dock narrows with the window, well below the 429px design frame, and
 99	  // a header that wraps there silently costs the thread a row. The label on
100	  // the left must clip instead, so the state on the right is always whole.
101	  it('keeps the setup card header on one line', () => {
102	    const rule = css.match(/\.current-setup-header\s*\{[^}]*\}/);
103	    expect(rule).not.toBeNull();
104	    expect(rule![0]).toMatch(/white-space:\s*nowrap/);
105	    const label = css.match(/\.current-setup-label\s*\{[^}]*\}/);
106	    expect(label).not.toBeNull();
107	    expect(label![0]).toMatch(/text-overflow:\s*ellipsis/);
108	  });
109	});

